<?php
require_once __DIR__.'/relationships.php';
function participant_api(mysqli $db,string $table,string $folder):never{
 $a=ed_start($db);$method=$_SERVER['REQUEST_METHOD'];$admin=in_array($a['role'],['admin','super_admin','lpk'],true);$learner=$a['role']==='peserta_intensif'&&$table==='peserta_intensif';$teacher=$a['role']==='sensei'&&$table==='peserta_intensif';if(!$admin&&!$learner&&!$teacher)ac_fail('Akses profil peserta tidak diizinkan.',403);if(!ac_table($db,$table))ac_fail('Modul peserta belum dikonfigurasi.',503);
 $columns=ac_rows($db,'SHOW COLUMNS FROM `'.$table.'`');$allowed=array_column($columns,'Field');$files=array_values(array_filter($allowed,fn($k)=>str_starts_with($k,'file_')||str_starts_with($k,'foto')||in_array($k,['sertifikat','dokumen','dokumen_hasil'],true)));
 if($method==='GET'){
  if($teacher){rs_ready($db);ed_respond(200,['status'=>'success','data'=>rs_roster($db,$a)]);}
  $student=$learner?rs_student($db,$a):null;
  if(($_GET['view']??'')==='file'){$id=ac_id($_GET['id']??null);if($student&&$id!==(int)$student['id'])ac_fail('Dokumen peserta lain ditolak.',403);$field=$_GET['field']??'';if(!in_array($field,$files,true))ac_fail('Dokumen tidak valid.');$r=ac_one($db,'SELECT `'.$field.'` AS file FROM `'.$table.'` WHERE id=?',[$id]);if(!$r)ac_fail('Dokumen tidak ditemukan.',404);rs_file('participants_'.$folder,$r['file']??'',$folder);}
  $rows=ac_rows($db,'SELECT * FROM `'.$table.'`'.($student?' WHERE id='.(int)$student['id']:'').' ORDER BY id DESC');if(($_GET['view']??'')==='directory'){$fields=[];foreach($columns as $column){$k=$column['Field'];if(in_array($k,['id','user_id','created_at','updated_at','password','password_hash','pin_hash'],true))continue;$fields[]=['name'=>$k,'type'=>$column['Type'],'required'=>$column['Null']==='NO'&&$column['Default']===null,'file'=>in_array($k,$files,true)];}ed_respond(200,['status'=>'success','data'=>['rows'=>$rows,'fields'=>$fields,'can_manage'=>$admin]]);}ed_respond(200,['status'=>'success','data'=>$rows]);
 }
 if(!$admin)ac_fail('Profil dikelola administrator/LPK.',403);if($method==='DELETE')ac_fail('Profil peserta dipertahankan untuk histori.',409);if(!in_array($method,['POST','PUT'],true))ac_fail('Metode tidak diizinkan.',405);
 $d=json_decode(file_get_contents('php://input'),true)??$_POST;if(!is_array($d))ac_fail('Data tidak valid.');$result=ac_atomic($db,function()use($db,$a,$table,$columns,$d,$files,$folder){
  ac_one($db,'SELECT id FROM roles ORDER BY id LIMIT 1 FOR UPDATE');$id=empty($d['id'])?null:ac_id($d['id']);$old=$id?ac_one($db,'SELECT * FROM `'.$table.'` WHERE id=? FOR UPDATE',[$id]):null;if($id&&!$old)ac_fail('Peserta tidak ditemukan.',404);if(isset($d['user_id'])&&(string)$d['user_id']!==(string)($old['user_id']??''))ac_fail('Relasi akun harus direview melalui pengelolaan akun; tidak diinfer otomatis.',409);
  $values=[];foreach($columns as $col){$k=$col['Field'];if(in_array($k,['id','user_id','created_at','updated_at','password','password_hash','pin_hash'],true))continue;if(in_array($k,$files,true)){$file=rs_upload($k,'participants_'.$folder);if($file)$values[$k]=$file;continue;}if(!array_key_exists($k,$d))continue;$v=$d[$k];if($v===''&&$col['Null']==='YES')$v=null;if($v!==null){$max=preg_match('/varchar\((\d+)\)/',$col['Type'],$m)?(int)$m[1]:10000;if(!is_string($v)&&!is_int($v))ac_fail('Field peserta tidak valid.');$v=ac_text((string)$v,$k,$max,false);}if($v!==null&&$col['Type']==='date')$v=ac_date($v);if($v!==null&&str_starts_with($col['Type'],'int')&&!preg_match('/^-?\d+$/D',(string)$v))ac_fail('Field numerik tidak valid.');if($k==='email'&&$v&&!filter_var($v,FILTER_VALIDATE_EMAIL))ac_fail('Email tidak valid.');$values[$k]=$v;}
  $name=$values['nama_lengkap']??$old['nama_lengkap']??'';if(!$old)foreach($columns as $column){$key=$column['Field'];if(in_array($key,['id','user_id','created_at','updated_at'],true)||$column['Null']!=='NO'||$column['Default']!==null)continue;if(!array_key_exists($key,$values)||$values[$key]==='')ac_fail('Field wajib belum lengkap: '.$key);}if(trim($name)==='')ac_fail('Nama peserta wajib diisi.');$email=$values['email']??$old['email']??null;if($email&&ac_one($db,'SELECT id FROM `'.$table.'` WHERE LOWER(TRIM(email))=LOWER(?) AND id<>?',[$email,$id??0]))ac_fail('Email peserta sudah ada; gunakan profil yang ada.',409);
  if($old&&$table==='peserta_intensif'&&$old['user_id']&&isset($values['email'])){if(ac_one($db,'SELECT id FROM users WHERE email=? AND id<>?',[$values['email'],(int)$old['user_id']]))ac_fail('Email akun sudah digunakan.',409);ac_query($db,'UPDATE users SET email=?,updated_at=NOW() WHERE id=?',[$values['email'],(int)$old['user_id']]);}
  if(!$values)ac_fail('Tidak ada perubahan valid.');$keys=array_keys($values);$sql=$old?'UPDATE `'.$table.'` SET '.implode(',',array_map(fn($k)=>'`'.$k.'`=?',$keys)).' WHERE id=?':'INSERT INTO `'.$table.'` ('.implode(',',array_map(fn($k)=>'`'.$k.'`',$keys)).') VALUES('.implode(',',array_fill(0,count($keys),'?')).')';ac_query($db,$sql,$old?[...array_values($values),$id]:array_values($values));if(!$old)$id=$db->insert_id;
  if($old&&$table==='peserta_intensif'&&$old['user_id']&&isset($values['nama_lengkap']))ac_query($db,'UPDATE employees SET full_name=?,updated_at=NOW() WHERE user_id=?',[$values['nama_lengkap'],(int)$old['user_id']]);rs_audit($db,$a,$table,$id,$old?'updated':'created',['fields'=>$keys]);return ['id'=>$id];
 });ed_respond(200,['status'=>'success','id'=>$result['id'],'data'=>$result]);
}
